637	function isAcceptedPattern(pattern: any): pattern is RemotePattern {
638		if (pattern == null) {
639			return false;
640		}
641		if (!pattern.hostname) {
642			return false;
643		}
644		if (pattern.protocol && (pattern.protocol !== 'http' || pattern.protocol !== 'https')) {
645			return false;
646		}
647		return true;
648	}
