674				{
675					entry,
676					outDir: functionFolder,
677					includeFiles,
678					excludeFiles,
679					logger,
680					root,
681				},
682				NTF_CACHE,
683			);
684	
685			// Enable ESM
686			// https://aws.amazon.com/blogs/compute/using-node-js-es-modules-and-top-level-await-in-aws-lambda/
687			await writeJson(packageJson, {
688				type: 'module',
689			});
690	
691			// Serverless function config
692			// https://vercel.com/docs/build-output-api/v3#vercel-primitives/serverless-functions/configuration
693			await writeJson(vcConfig, {
694				runtime,
695				handler: handler.replaceAll('\\', '/'),
696				launcherType: 'Nodejs',
697				maxDuration,
698				supportsResponseStreaming: true,
699			});
700		}
