736	function getRuntime(process: NodeJS.Process, logger: AstroIntegrationLogger): Runtime {
737		const version = process.version.slice(1); // 'v18.19.0' --> '18.19.0'
738		const major = version.split('.')[0]; // '18.19.0' --> '18'
739		const support = SUPPORTED_NODE_VERSIONS[major];
740		if (support === undefined) {
741			logger.warn(
742				`\n` +
743					`\tThe local Node.js version (${major}) is not supported by Vercel Serverless Functions.\n` +
744					`\tYour project will use Node.js 24 as the runtime instead.\n` +
745					`\tConsider switching your local version to 24.\n`,
746			);
747			return 'nodejs24.x';
748		}
749		if (support.status === 'default' || support.status === 'available') {
750			return `nodejs${major}.x`;
751		}
752		if (support.status === 'retiring') {
753			if (support.warnDate && new Date() >= support.warnDate) {
754				logger.warn(
755					`Your project is being built for Node.js ${major} as the runtime, which is retiring by ${support.removal}.`,
756				);
757			}
758			return `nodejs${major}.x`;
759		}
760		if (support.status === 'beta') {
761			logger.warn(
762				`Your project is being built for Node.js ${major} as the runtime, which is currently in beta for Vercel Serverless Functions.`,
763			);
764			return `nodejs${major}.x`;
765		}
766		if (support.status === 'deprecated') {
767			logger.warn(
768				`\n` +
769					`\tYour project is being built for Node.js ${major} as the runtime.\n` +
770					`\tThis version is deprecated by Vercel Serverless Functions.\n` +
771					`\tConsider upgrading your local version to 24.\n`,
772			);
773			return `nodejs${major}.x`;
774		}
775		return 'nodejs24.x';
776	}
