778	function createRoutesWithStaticHeaders(
779		staticHeaders: RouteToHeaders,
780		config: AstroConfig,
781	): RouteWithSrc[] {
782		const vercelHeaders: RouteWithSrc[] = [];
783		for (const [pathname, { headers }] of staticHeaders.entries()) {
784			if (config.security.csp) {
785				const csp = headers.get('Content-Security-Policy');
786	
787				if (csp) {
788					const _headers = {
789						'content-security-policy': csp,
790					};
791					vercelHeaders.push({
792						src: pathname,
793						headers: _headers,
794					});
795				}
796			}
797		}
798	
799		return vercelHeaders;
800	}
