13	 * It generates the Vercel Edge Middleware file.
14	 *
15	 * It creates a temporary file, the edge middleware, with some dynamic info.
16	 *
17	 * Then this file gets bundled with esbuild. The bundle phase will inline the Astro middleware code.
18	 *
19	 * @param astroMiddlewareEntryPointPath
20	 * @param root
21	 * @param vercelEdgeMiddlewareHandlerPath
22	 * @param outPath
23	 * @param middlewareSecret
24	 * @param logger
25	 * @returns {Promise<URL>} The path to the bundled file
26	 */
27	export async function generateEdgeMiddleware(
28		astroMiddlewareEntryPointPath: URL,
29		root: URL,
30		vercelEdgeMiddlewareHandlerPath: URL,
31		outPath: URL,
32		middlewareSecret: string,
33		logger: AstroIntegrationLogger,
34	): Promise<URL> {
35		const code = edgeMiddlewareTemplate(
36			astroMiddlewareEntryPointPath,
37			vercelEdgeMiddlewareHandlerPath,
38			middlewareSecret,
39			logger,
