57				conditions: ['edge-light', 'workerd', 'worker'],
58				outfile: bundledFilePath,
59				allowOverwrite: true,
60				format: 'esm',
61				bundle: true,
62				minify: false,
63				// ensure node built-in modules are namespaced with `node:`
64				plugins: [
65					{
66						name: 'esbuild-namespace-node-built-in-modules',
67						setup(build) {
68							const filter = new RegExp(builtinModules.map((mod) => `(^${mod}$)`).join('|'));
69							build.onResolve(
70								{
71									filter,
72								},
73								(args) => ({
74									path: 'node:' + args.path,
75									external: true,
76								}),
77							);
78						},
79					},
80				],
81			});
82		} catch (err) {
83			if ((err as Error).message.includes('Could not resolve "node:')) {
84				logger.error(
85					`Vercel does not allow the use of Node.js built-ins in edge functions. Please ensure your middleware code and 3rd-party packages don’t use Node built-ins.`,
86				);
87			}
