94	function edgeMiddlewareTemplate(
95		astroMiddlewareEntryPointPath: URL,
96		vercelEdgeMiddlewareHandlerPath: URL,
97		middlewareSecret: string,
98		logger: AstroIntegrationLogger,
99	) {
100		const middlewarePath = JSON.stringify(
101			fileURLToPath(astroMiddlewareEntryPointPath).replace(/\\/g, '/'),
102		);
103		const filePathEdgeMiddleware = fileURLToPath(vercelEdgeMiddlewareHandlerPath);
104		let handlerTemplateImport = '';
105		let handlerTemplateCall = '{}';
106		if (existsSync(filePathEdgeMiddleware + '.js') || existsSync(filePathEdgeMiddleware + '.ts')) {
107			logger.warn(
108				'Usage of `vercel-edge-middleware.js` is deprecated. You can now use the `waitUntil(promise)` function directly as `ctx.locals.waitUntil(promise)`.',
109			);
110			const stringified = JSON.stringify(filePathEdgeMiddleware.replace(/\\/g, '/'));
111			handlerTemplateImport = `import handler from ${stringified}`;
112			handlerTemplateCall = `await handler({ request, context })`;
113		} else {
114		}
115		return `
116		${handlerTemplateImport}
117	import { onRequest } from ${middlewarePath};
118	import { createContext, trySerializeLocals } from 'astro/middleware';
119	export default async function middleware(request, context) {
120		const ctx = createContext({
121			request,
122			params: {},
123			clientAddress: request.headers.get('x-real-ip') || undefined,
124		});
125		Object.assign(ctx.locals, { vercel: { edge: context }, ...${handlerTemplateCall} });
126		const { origin } = new URL(request.url);
127		const next = async () => {
128			const { vercel, ...locals } = ctx.locals;
129			const response = await fetch(new URL('/${NODE_PATH}', request.url), {
130				headers: {
131					...Object.fromEntries(request.headers.entries()),
132					'${ASTRO_MIDDLEWARE_SECRET_HEADER}': '${middlewareSecret}',
133					'${ASTRO_PATH_HEADER}': request.url.replace(origin, ''),
134					'${ASTRO_LOCALS_HEADER}': trySerializeLocals(locals)
135				}
136			});
137			return new Response(response.body, {
138				status: response.status,
139				statusText: response.statusText,
140				headers: response.headers,
141			});
142		};
143	
144		const response = await onRequest(ctx, next);
145		// Append cookies from Astro.cookies
146		for(const setCookieHeaderValue of ctx.cookies.headers()) {
147			response.headers.append('set-cookie', setCookieHeaderValue);
148		}
149		return response;
150	}`;
151	}
